// -------------------------- RC4 密钥（XOR 混淆存储，运行时还原） --------------------------
static const uint8_t RC4_KEY_BYTES[24] = {0x3F, 0x19, 0x3B, 0x1E, 0x33, 0x04, 0x14, 0x03, 0x13, 0x0E, 0x25, 0x0A, 0x3C, 0x69, 0x3C, 0x6D, 0x2C, 0x0B, 0x18, 0x0E, 0x55, 0x0D, 0x53, 0x0B};
static const uint8_t RC4_KEY_MASK[24]  = {0x4D, 0x4E, 0x4F, 0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F, 0x60, 0x61, 0x62, 0x63, 0x64};
static const size_t RC4_KEY_LEN = 24;

static bool rc4KeyReady = false;
static uint8_t rc4Key[24];

static const uint8_t *getRc4Key() {
    if (!rc4KeyReady) {
        for (size_t i = 0; i < RC4_KEY_LEN; ++i) {
            rc4Key[i] = RC4_KEY_BYTES[i] ^ RC4_KEY_MASK[i];
        }
        rc4KeyReady = true;
    }
    return rc4Key;
}

// -------------------------- RC4 加解密（同一函数，对称流加密） --------------------------
static void rc4Crypt(const uint8_t *data, size_t len,
                     const uint8_t *key, size_t keyLen, uint8_t *out) {
    uint8_t S[256];
    for (int i = 0; i < 256; ++i) S[i] = static_cast<uint8_t>(i);

    int j = 0;
    for (int i = 0; i < 256; ++i) {
        j = (j + S[i] + key[i % keyLen]) & 0xFF;
        std::swap(S[i], S[j]);
    }

    int x = 0;
    j = 0;
    for (size_t n = 0; n < len; ++n) {
        x = (x + 1) & 0xFF;
        j = (j + S[x]) & 0xFF;
        std::swap(S[x], S[j]);
        out[n] = data[n] ^ S[(S[x] + S[j]) & 0xFF];
    }
}

// -------------------------- FNV-1a 64 位哈希：分组名不再明文存储 --------------------------
static uint64_t fnv1a64(const std::string &s) {
    uint64_t h = 0xcbf29ce484222325ULL;
    for (char c : s) {
        h ^= static_cast<uint8_t>(c);
        h *= 0x100000001b3ULL;
    }
    return h;
}

